"use client";

import { useMemo } from "react";
import { GodLights } from "godlights";
import type { SceneConfig } from "godlights";

interface GodLightsBackgroundProps {
  /** Primary ray/halo color (hex). Default: "#a78bfa" */
  color?: string;
  /** Background fill color (hex). Default: "#06060f" */
  bgColor?: string;
  /** Enable animation loop. Default: true */
  animate?: boolean;
  children?: React.ReactNode;
  style?: React.CSSProperties;
  className?: string;
}

export function GodLightsBackground({
  color = "#a78bfa",
  bgColor = "#06060f",
  animate = true,
  children,
  style,
  className,
}: GodLightsBackgroundProps) {
  const scene: SceneConfig = useMemo(
    () => ({
      width: 1920,
      height: 1080,
      noise: 6,
      grainSize: 1,
      layers: [
        {
          id: "background",
          type: "background",
          bgType: "solid",
          bgColor,
          bgColor2: bgColor,
          bgGradientAngle: 180,
        },
        {
          id: "halo-1",
          name: "Halo",
          type: "halo",
          originX: 50,
          originY: 0,
          color,
          intensity: 0.25,
          size: 0.45,
          blendMode: "lighter",
        },
        {
          id: "rays-1",
          name: "Rays",
          type: "rays",
          direction: 180,
          spread: 100,
          originX: 50,
          originY: -10,
          rayCount: 20,
          rayWidth: 70,
          divergence: 1.6,
          rayLength: 1.0,
          colorStart: color,
          colorEnd: color,
          opacity: 0.15,
          blendMode: "screen",
          fadeToTransparent: true,
          blur: 10,
          randomnessWidth: 60,
          randomnessLength: 20,
          randomnessAngle: 15,
          seed: 1,
        },
      ],
    }),
    [color, bgColor]
  );

  return (
    <div className={className} style={{ position: "relative", ...style }}>
      <GodLights
        scene={scene}
        animate={animate}
        style={{
          position: "absolute",
          inset: 0,
          width: "100%",
          height: "100%",
        }}
      />
      <div style={{ position: "relative", zIndex: 1 }}>{children}</div>
    </div>
  );
}
